import { useEffect, useRef } from 'react';
import { batch, useDispatch, useSelector } from 'react-redux';

import { commonActions } from 'app/services/CommonService';
import {
  KeyCode,
  keyboardActions,
  useKeyboardSlice,
} from 'app/services/KeyboardService';
import { getKeyboardNote } from 'app/services/KeyboardService/noteByKey';
import {
  Note,
  Octave,
  getNote,
  notesActions,
  pitchNote,
  selectHasRecordedNotes,
  useNotesSlice,
} from 'app/services/NotesService';
import { selectSettings, useSettingsSlice } from 'app/services/SettingsService';
import { noteTuningCents } from 'app/services/SettingsService/microtonal';
import { Timbre, activateHarmonics } from 'app/services/SynthesizerService';

import { isFormInputTarget } from 'utils/isFormInputTarget';

const isCommandKey = (event: KeyboardEvent) =>
  event.key === 'Meta' ||
  event.code === 'MetaLeft' ||
  event.code === 'MetaRight';

const isOptionKey = (event: KeyboardEvent) =>
  event.key === 'Alt' || event.code === 'AltLeft' || event.code === 'AltRight';

export const useKeyboard = (scope: string | null = 'keyboard') => {
  useNotesSlice();
  useKeyboardSlice();
  useSettingsSlice();
  const dispatch = useDispatch();
  const {
    octave,
    pitch,
    applicature,
    scaleNotes,
    timbre,
    isRecording,
    scale,
    mode,
  } = useSelector(selectSettings);
  const hasRecordedNotes = useSelector(selectHasRecordedNotes);

  const getNoteByKey = (key: KeyCode) =>
    getKeyboardNote(key, { applicature, scaleNotes, octave, pitch, timbre });

  const stateRef = useRef({
    getNoteByKey,
    timbre,
    isRecording,
    hasRecordedNotes,
    applicature,
    scale,
    mode,
    pitch,
  });
  stateRef.current = {
    getNoteByKey,
    timbre,
    isRecording,
    hasRecordedNotes,
    applicature,
    scale,
    mode,
    pitch,
  };

  useEffect(() => {
    if (scope === null) return;

    const commandKeys = new Set<string>();
    const optionKeys = new Set<string>();
    const pressedNotes = new Map<
      KeyCode,
      {
        note: Note;
        timbre: Timbre;
        isRecording: boolean;
        startedWithCommand: boolean;
      }
    >();
    let blurTimeout: number | undefined;

    const releaseNote = (key: KeyCode) => {
      const played = pressedNotes.get(key);
      pressedNotes.delete(key);
      dispatch(keyboardActions.removePressedKey(key));
      if (played) {
        dispatch(notesActions.muteNote(played));
        if (played.isRecording) {
          dispatch(notesActions.logEndingNote(played.note));
        }
      }
    };

    const releaseAllNotes = () => {
      batch(() => {
        Array.from(pressedNotes.keys()).forEach(releaseNote);
        dispatch(keyboardActions.resetPressedKeys());
      });
    };

    const reset = () => {
      commandKeys.clear();
      optionKeys.clear();
      releaseAllNotes();
    };

    const handleKeydown = (event: KeyboardEvent) => {
      if (isFormInputTarget(event.target) || event.isComposing) return;

      if (!event.altKey && !isOptionKey(event)) {
        optionKeys.clear();
      }
      const withCommand = event.metaKey || commandKeys.size > 0;
      if (withCommand) {
        // Cancel shortcuts before ignoring arrows, unmapped keys or repeats.
        event.preventDefault();
      }
      if (isCommandKey(event)) {
        event.preventDefault();
        commandKeys.add(event.code);
        return;
      }
      if (isOptionKey(event)) {
        event.preventDefault();
        if (!event.repeat && !optionKeys.size) {
          activateHarmonics();
        }
        optionKeys.add(event.code);
        return;
      }
      const state = stateRef.current;
      const key = event.code as KeyCode;
      const note = state.getNoteByKey(key);
      if (
        !withCommand &&
        ((event.code === 'Space' &&
          event.target instanceof Element &&
          event.target.closest('[data-local-space-key]')) ||
          (!note && ['Tab', 'Enter', 'Space'].includes(event.code)))
      ) {
        return;
      }
      if (
        ['ArrowLeft', 'ArrowUp', 'ArrowRight', 'ArrowDown'].includes(key) ||
        (withCommand && !note)
      ) {
        return;
      }
      event.preventDefault();
      if (event.repeat) {
        return;
      }
      batch(() => {
        // A fresh keydown proves the previous press ended even if keyup was lost.
        if (pressedNotes.has(key)) releaseNote(key);
        dispatch(keyboardActions.addPressedKey(key));
        if (note) {
          const tuningCents = noteTuningCents(note, state);
          const played = {
            note,
            timbre: state.timbre,
            ...(tuningCents ? { tuningCents } : {}),
          };
          pressedNotes.set(key, {
            ...played,
            isRecording: state.isRecording,
            startedWithCommand: withCommand,
          });
          dispatch(notesActions.playNote(played));
          if (event.altKey || optionKeys.size > 0) {
            activateHarmonics(played);
          }
          if (state.isRecording) {
            dispatch(notesActions.logStartingNote(note));
          }
        }
      });
      if (!state.hasRecordedNotes && blurTimeout === undefined) {
        blurTimeout = window.setTimeout(() => {
          blurTimeout = undefined;
          dispatch(commonActions.blurSettings());
        }, 3000);
      }
    };

    const handleKeyup = (event: KeyboardEvent) => {
      if (isFormInputTarget(event.target)) return;

      if (!event.altKey) optionKeys.clear();
      if (isOptionKey(event)) {
        event.preventDefault();
        optionKeys.delete(event.code);
        return;
      }
      if (isCommandKey(event)) {
        event.preventDefault();
        commandKeys.delete(event.code);
        if (!commandKeys.size && !event.metaKey) {
          // macOS can omit keyup for notes played under Command. Keep notes
          // already held before Command sounding until their own keyup.
          batch(() => {
            Array.from(pressedNotes.entries()).forEach(([key, played]) => {
              if (played.startedWithCommand) {
                releaseNote(key);
              }
            });
          });
        }
        return;
      }
      const key = event.code as KeyCode;
      if (
        !pressedNotes.has(key) &&
        ['Tab', 'Enter', 'Space'].includes(event.code)
      ) {
        return;
      }
      event.preventDefault();
      batch(() => releaseNote(key));
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        reset();
      }
    };

    const handleFocus = (event: FocusEvent) => {
      if (
        (event.target === window && !event.relatedTarget) ||
        isFormInputTarget(event.target)
      ) {
        reset();
      }
    };

    window.addEventListener('keydown', handleKeydown, true);
    window.addEventListener('keyup', handleKeyup, true);
    window.addEventListener('blur', reset);
    window.addEventListener('focus', handleFocus, true);
    window.addEventListener('pagehide', reset);
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      reset();
      window.clearTimeout(blurTimeout);
      window.removeEventListener('keydown', handleKeydown, true);
      window.removeEventListener('keyup', handleKeyup, true);
      window.removeEventListener('blur', reset);
      window.removeEventListener('focus', handleFocus, true);
      window.removeEventListener('pagehide', reset);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [dispatch, scope]);

  useEffect(() => {
    const notes = scaleNotes.map(justNote =>
      // TODO: as Octave to save getOctave function
      pitchNote(getNote(justNote, (octave + 1) as Octave), pitch),
    );
    batch(() => {
      dispatch(notesActions.playdownAllNotes());
      notes.forEach(note => {
        dispatch(notesActions.highlightNote(note));
      });
    });
  }, [dispatch, scaleNotes, pitch, octave]);
};
