import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { prepareInstrumentSample } from 'app/services/SynthesizerService';
import {
  EffectsRack,
  createEffectsRack,
} from 'app/services/SynthesizerService/effects';
import { Timbre } from 'app/services/SynthesizerService/types';

import { GuitarCapture } from './capture';
import { prepareTimbreLoop } from './timbreLoop';
import { TimbreMonitor } from './timbreMonitor';

const modules = new WeakMap<AudioContext, Promise<void>>();
const loadProcessor = (audio: AudioContext) => {
  let loading = modules.get(audio);
  if (!loading) {
    loading = audio.audioWorklet.addModule(
      `${process.env.PUBLIC_URL}/timbre-loop.worklet.js?v=1`,
    );
    modules.set(audio, loading);
    void loading.catch(() => modules.delete(audio));
  }
  return loading;
};

// One non-decaying carrier runs for the whole session. AudioWorklet outputs
// continuously modulate its playbackRate and gain without messages or note IDs.
export const createTimbreTransfer = (
  input: GuitarCapture,
  timbre: Timbre,
  settings: InstrumentEffects,
  amount: number,
  onError: (error: Error) => void,
): TimbreMonitor => {
  const audio = input.audioContext;
  let disposed = false;
  let processor: AudioWorkletNode | undefined;
  let rack: EffectsRack | undefined;
  let gate: GainNode | undefined;
  let meter: AnalyserNode | undefined;
  let carrier: AudioBufferSourceNode | undefined;
  let envelope: GainNode | undefined;
  let wet: GainNode | undefined;
  let dry: GainNode | undefined;
  let connected = false;
  let dryConnected = false;
  let started = false;
  const data = new Float32Array(1024);
  const setAmount = (value: number) => {
    amount = Math.max(0, Math.min(100, value));
    wet?.gain.setTargetAtTime(amount / 100, audio.currentTime, 0.01);
    dry?.gain.setTargetAtTime(1 - amount / 100, audio.currentTime, 0.01);
  };
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    if (gate) {
      gate.gain.cancelScheduledValues(audio.currentTime);
      gate.gain.setValueAtTime(0, audio.currentTime);
      gate.disconnect();
    }
    if (processor) {
      processor.onprocessorerror = null;
      if (connected) input.inputNode.disconnect(processor);
      processor.disconnect();
      processor.port.postMessage({ dispose: true });
      processor.port.close();
    }
    if (started) carrier?.stop();
    carrier?.disconnect();
    envelope?.disconnect();
    wet?.disconnect();
    if (dry && dryConnected) input.inputNode.disconnect(dry);
    dry?.disconnect();
    rack?.dispose();
    meter?.disconnect();
  };
  const ready = Promise.all([
    prepareInstrumentSample(timbre),
    loadProcessor(audio),
  ]).then(([buffer]) => {
    if (disposed) return;
    const table = prepareTimbreLoop(buffer, timbre);
    const loop = audio.createBuffer(1, table.length, audio.sampleRate);
    loop.getChannelData(0).set(table);
    processor = new AudioWorkletNode(audio, 'qwertophone-timbre-loop', {
      numberOfInputs: 1,
      numberOfOutputs: 2,
      channelCount: 1,
      channelCountMode: 'explicit',
      outputChannelCount: [1, 1],
      processorOptions: { referenceFrequency: audio.sampleRate / table.length },
    });
    processor.onprocessorerror = () => {
      if (disposed) return;
      dispose();
      onError(
        new Error(
          'Loop control interrupted. Turn off live sound and try again.',
        ),
      );
    };
    gate = audio.createGain();
    gate.gain.value = 0;
    meter = audio.createAnalyser();
    meter.fftSize = data.length;
    gate.connect(meter).connect(audio.destination);
    rack = createEffectsRack(audio, gate, settings, {
      lowLatency: true,
      cursorKey: timbre,
      continuousCursor: true,
    });
    carrier = audio.createBufferSource();
    carrier.buffer = loop;
    carrier.loop = true;
    carrier.loopStart = 0;
    carrier.loopEnd = table.length / audio.sampleRate;
    carrier.playbackRate.value = 0;
    envelope = audio.createGain();
    envelope.gain.value = 0;
    wet = audio.createGain();
    dry = audio.createGain();
    wet.gain.value = amount / 100;
    dry.gain.value = 1 - amount / 100;
    carrier.connect(envelope).connect(wet).connect(rack.input);
    input.inputNode.connect(dry).connect(rack.input);
    dryConnected = true;
    processor.connect(carrier.playbackRate, 0);
    processor.connect(envelope.gain, 1);
    setAmount(amount);
    input.inputNode.connect(processor);
    connected = true;
    carrier.start();
    started = true;
    gate.gain.setValueAtTime(0, audio.currentTime);
    gate.gain.linearRampToValueAtTime(1, audio.currentTime + 0.004);
  });
  return {
    ready,
    dispose,
    setAmount,
    updateEffects(value) {
      settings = value;
      rack?.update(value);
    },
    level() {
      if (disposed || !meter) return { rms: 0, peak: 0 };
      meter.getFloatTimeDomainData(data);
      let energy = 0,
        peak = 0;
      data.forEach(value => {
        energy += value * value;
        peak = Math.max(peak, Math.abs(value));
      });
      return { rms: Math.sqrt(energy / data.length), peak };
    },
  };
};
