import { useEffect, useRef, useState } from 'react';

import {
  isInstrumentAudioRunning,
  loadVirtualGuitar,
  playVirtualGuitarNote,
  resumeAudio,
} from 'app/services/SynthesizerService';

import { bendAtDistance, noteAtFret, slideFret } from './fretboard';

type GuitarVoice = NonNullable<ReturnType<typeof playVirtualGuitarNote>>;

interface PointerOrigin {
  y: number;
  type: string;
}

interface Gesture {
  fret: number;
  bendCents: number;
  bendDirection: number;
}

type Technique =
  | { kind: 'slide'; fret: number; direction: number }
  | { kind: 'bend'; cents: number }
  | { kind: 'release' };

export interface GuitarTabNote {
  id: number;
  string: number;
  fret: number;
  techniques?: Technique[];
}

export const guitarTabLength = 8;

interface HeldString extends GuitarTabNote {
  origin?: PointerOrigin;
  gesture?: Gesture;
  bendIndex?: number;
  voice?: GuitarVoice;
  unlockOnRelease: boolean;
  released?: boolean;
  timer?: number;
}

export const useVirtualGuitar = (enabled: boolean) => {
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>(
    'loading',
  );
  const [attempt, setAttempt] = useState(0);
  const held = useRef(new Map<number, HeldString>());
  const [active, setActive] = useState<HeldString[]>([]);
  const nextTabId = useRef(0);
  const [tab, setTab] = useState<GuitarTabNote[]>([]);

  useEffect(() => {
    let current = true;
    loadVirtualGuitar().then(
      () => current && setStatus('ready'),
      () => current && setStatus('error'),
    );
    return () => {
      current = false;
    };
  }, [attempt]);

  useEffect(() => {
    if (!enabled) {
      setActive([]);
      return;
    }
    const strings = held.current;
    const clear = () => {
      strings.forEach(({ timer, voice }) => {
        window.clearTimeout(timer);
        voice?.stop();
      });
      strings.clear();
    };
    const reset = () => {
      clear();
      setActive([]);
    };
    const visibility = () => {
      if (document.hidden) reset();
    };
    window.addEventListener('blur', reset);
    window.addEventListener('pagehide', reset);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      clear();
      window.removeEventListener('blur', reset);
      window.removeEventListener('pagehide', reset);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [enabled]);

  const refresh = () =>
    setActive(Array.from(held.current.values()).filter(note => note.voice));
  const cancel = (id: number) => {
    const note = held.current.get(id);
    if (!note) return;
    held.current.delete(id);
    window.clearTimeout(note.timer);
    note.voice?.stop();
    if (note.voice) refresh();
  };

  const start = (pointer: number, tabId: number) => {
    const fail = () => {
      if (held.current.get(pointer)?.id !== tabId) return;
      cancel(pointer);
      setStatus('error');
    };
    const pluck = () => {
      const note = held.current.get(pointer);
      if (note?.id !== tabId) return;
      const { string, fret, gesture, techniques } = note;
      const voice = playVirtualGuitarNote(noteAtFret(string, fret));
      if (!voice) {
        fail();
        return;
      }
      if (gesture && gesture.fret !== fret)
        voice.setSlideOffset(gesture.fret - fret);
      if (gesture?.bendCents) voice.setBend(gesture.bendCents);
      note.voice = voice;
      if (!note.origin || note.released)
        note.timer = window.setTimeout(() => cancel(pointer), 360);
      setTab(current => [
        ...current.slice(1 - guitarTabLength),
        { id: tabId, string, fret, techniques },
      ]);
      setStatus('ready');
      refresh();
    };
    if (status === 'ready' && isInstrumentAudioRunning()) pluck();
    else
      void Promise.all([resumeAudio(), loadVirtualGuitar()])
        .then(pluck)
        .catch(fail);
  };

  return {
    status,
    active,
    tab,
    retry: () => {
      setStatus('loading');
      setAttempt(count => count + 1);
    },
    play: (
      id: number,
      string: number,
      fret: number,
      origin?: PointerOrigin,
    ) => {
      if (!enabled) return;
      held.current.forEach((note, owner) => {
        if (note.string === string || owner === id) cancel(owner);
      });
      const tabId = nextTabId.current++;
      const unlockOnRelease =
        !!origin && origin.type !== 'mouse' && !isInstrumentAudioRunning();
      held.current.set(id, {
        id: tabId,
        string,
        fret,
        origin,
        unlockOnRelease,
      });
      if (!unlockOnRelease) start(id, tabId);
    },
    move: (id: number, y: number, cellOffset: number) => {
      const note = held.current.get(id);
      if (!note?.origin || note.released) return;
      const dy = y - note.origin.y;
      const fret = slideFret(note.fret, cellOffset);
      const bendCents = bendAtDistance(dy);
      const bendDirection = bendCents ? Math.sign(dy) : 0;
      const previousFret = note.gesture?.fret ?? note.fret;
      const fretChanged = fret !== previousFret;
      const bendChanged = bendCents !== (note.gesture?.bendCents ?? 0);
      if (
        !fretChanged &&
        !bendChanged &&
        bendDirection === (note.gesture?.bendDirection ?? 0)
      )
        return;

      if (fretChanged) note.voice?.setSlideOffset(fret - note.fret);
      if (bendChanged) note.voice?.setBend(bendCents);
      const gesture = { fret, bendCents, bendDirection };
      const { techniques, bendIndex } = recordTechniques(note, gesture);
      if (note.voice && techniques !== note.techniques)
        setTab(current =>
          current.map(entry =>
            entry.id === note.id ? { ...entry, techniques } : entry,
          ),
        );
      held.current.set(id, { ...note, gesture, techniques, bendIndex });
      if (note.voice) refresh();
    },
    release: (id: number) => {
      const note = held.current.get(id);
      if (!note || note.released) return;
      if (note.voice) {
        cancel(id);
        return;
      }
      // Keep a quick tap while the sample is loading. A fresh touch only
      // grants audio activation when the pointer is released.
      note.released = true;
      if (note.unlockOnRelease) start(id, note.id);
    },
    cancel,
    loseCapture: (id: number) => {
      if (!held.current.get(id)?.released) cancel(id);
    },
  };
};

const recordTechniques = (note: HeldString, { fret, bendCents }: Gesture) => {
  let { techniques, bendIndex } = note;
  const previousFret = note.gesture?.fret ?? note.fret;
  if (fret !== previousFret) {
    const direction = Math.sign(fret - previousFret);
    const recorded = techniques ?? [];
    const last = recorded[recorded.length - 1];
    // A continuous slide needs only its end fret.
    const continuing = last?.kind === 'slide' && last.direction === direction;
    techniques = [
      ...(continuing ? recorded.slice(0, -1) : recorded),
      { kind: 'slide', fret, direction },
    ];
  }
  const cents = Math.round(bendCents);
  if (bendIndex === undefined) {
    if (cents > 0) {
      bendIndex = techniques?.length ?? 0;
      techniques = [...(techniques ?? []), { kind: 'bend', cents }];
    }
  } else if (techniques) {
    const bend = techniques[bendIndex];
    if (bendCents === 0) {
      techniques = [...techniques, { kind: 'release' }];
      bendIndex = undefined;
    } else if (bend.kind === 'bend' && cents > bend.cents) {
      techniques = [...techniques];
      techniques[bendIndex] = { kind: 'bend', cents };
    }
  }
  return { techniques, bendIndex };
};
