import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import styled from 'styled-components';

import {
  VocalNote,
  frequencyPitch,
  pitchName,
  targetPitch,
} from 'app/services/KaraokeService/score';

export const KaraokeRoll = ({
  line,
  elapsed,
  frequency,
  playing,
  speed,
}: {
  line: VocalNote[];
  elapsed: number;
  frequency: number | null;
  playing: boolean;
  speed: number;
}) => {
  const container = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(1000);
  useLayoutEffect(() => {
    const measure = () =>
      setWidth(Math.max(320, (container.current?.clientWidth ?? 1000) - 2));
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver(measure);
    if (container.current) observer?.observe(container.current);
    window.addEventListener('resize', measure);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, []);
  const [trail, setTrail] = useState<{ time: number; pitch: number | null }[]>(
    [],
  );
  useEffect(() => {
    if (elapsed < 0) {
      setTrail([]);
      return;
    }
    if (!playing) return;
    setTrail(points => [
      ...points.filter(
        point => point.time >= elapsed - 2000 * speed && point.time < elapsed,
      ),
      { time: elapsed, pitch: frequency ? frequencyPitch(frequency) : null },
    ]);
  }, [elapsed, frequency, playing, speed]);
  const [low, high] = useMemo(() => {
    const pitches = line.flatMap(note => [
      note.pitch,
      ...(note.expression?.points.map(
        point => note.pitch + point.cents / 100,
      ) ?? []),
    ]);
    return [
      Math.floor(
        pitches.reduce((min, pitch) => Math.min(min, pitch), pitches[0] ?? 60),
      ) - 2,
      Math.ceil(
        pitches.reduce((max, pitch) => Math.max(max, pitch), pitches[0] ?? 60),
      ) + 2,
    ];
  }, [line]);
  const y = (pitch: number) => 280 - ((pitch - low) / (high - low)) * 250;
  const x = (time: number) =>
    60 + ((time - elapsed + 2000 * speed) / (8000 * speed)) * (width - 60);
  const step = Math.max(1, Math.ceil((high - low) / 18));
  let connected = false;
  const path = trail
    .map(point => {
      if (point.pitch === null) {
        connected = false;
        return '';
      }
      const command = connected ? 'L' : 'M';
      connected = true;
      return `${command}${x(point.time)},${y(
        Math.max(low, Math.min(high, point.pitch)),
      )}`;
    })
    .join(' ');
  return (
    <Roll ref={container} aria-label="Vocal notes and voice pitch">
      <svg
        viewBox={`0 0 ${width} 320`}
        role="img"
        aria-label="The melody moves from right to left. Sing the note at the vertical line."
      >
        <defs>
          <clipPath id="karaoke-lane">
            <rect x="58" y="10" width={width - 58} height="285" />
          </clipPath>
        </defs>
        {Array.from(
          { length: Math.floor((high - low) / step) + 1 },
          (_, index) => low + index * step,
        ).map(pitch => (
          <g key={pitch} className="grid">
            <line x1="58" x2={width} y1={y(pitch)} y2={y(pitch)} />
            <text x="6" y={y(pitch) + 4}>
              {pitchName(pitch)}
            </text>
          </g>
        ))}
        <g clipPath="url(#karaoke-lane)">
          {line
            .filter(
              note =>
                note.start + note.duration > elapsed - 2000 * speed &&
                note.start < elapsed + 6000 * speed,
            )
            .map((note, index) => (
              <g key={`${note.start}-${index}`}>
                <rect
                  x={x(note.start)}
                  y={y(note.pitch) - 8}
                  width={Math.max(
                    2,
                    x(note.start + note.duration) - x(note.start),
                  )}
                  height="16"
                  rx="5"
                  className="target"
                />
                {note.expression && (
                  <path
                    className="expression"
                    d={Array.from({ length: 21 }, (_, i) => {
                      const time = note.start + (note.duration * i) / 20;
                      return `${i ? 'L' : 'M'}${x(time)},${y(
                        targetPitch(note, time),
                      )}`;
                    }).join(' ')}
                  />
                )}
              </g>
            ))}
          <line
            x1={x(elapsed)}
            x2={x(elapsed)}
            y1="10"
            y2="295"
            className="now"
          />
          <path d={path} className="voice" />
          {frequency && (
            <circle
              cx={x(elapsed)}
              cy={y(Math.max(low, Math.min(high, frequencyPitch(frequency))))}
              r="7"
              className="dot"
            />
          )}
        </g>
        <text x={x(elapsed)} y="316" textAnchor="middle" className="caption">
          NOW
        </text>
      </svg>
      <Legend>
        <span>Bars: melody</span>
        <span>Line and dot: your voice</span>
      </Legend>
    </Roll>
  );
};

const Roll = styled.div`
  overflow: hidden;
  border: 1px solid ${p => p.theme.border};
  border-radius: 16px;
  background: ${p => p.theme.background};
  svg {
    display: block;
    width: 100%;
    height: 320px;
  }
  .grid {
    stroke: ${p => p.theme.border};
  }
  text {
    fill: ${p => p.theme.textSecondary};
    stroke: none;
    font: 12px sans-serif;
  }
  .target {
    fill: ${p => p.theme.primary};
    opacity: 0.5;
  }
  .now {
    stroke: ${p => p.theme.textSecondary};
    stroke-dasharray: 4 5;
  }
  .voice,
  .expression {
    fill: none;
    stroke: ${p => p.theme.text};
    stroke-width: 3;
    stroke-linejoin: round;
  }
  .expression {
    stroke: ${p => p.theme.primary};
    stroke-width: 2;
  }
  .dot {
    fill: ${p => p.theme.text};
  }
  .caption {
    font-size: 10px;
    letter-spacing: 1px;
  }
`;
const Legend = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 24px;
  padding: 10px;
  color: ${p => p.theme.textSecondary};
  font-size: 11px;
`;
