import styled from 'styled-components';

import type { Note } from 'app/services/NotesService/types';

import { getStringNoteNumber } from './utils';

import { STRINGS } from './mappings';
import type { StringInstrumentType } from './types';

export const getUnmappedNote = (instrument: StringInstrumentType, note: Note) =>
  STRINGS[instrument].some(
    string => getStringNoteNumber(instrument, string, note) !== '---',
  )
    ? undefined
    : note;

export const UnmappedNote = styled.span`
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  padding-bottom: 3px;
  color: ${p => p.theme.warning};
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  pointer-events: none;
`;
