import { useEffect, useRef } from 'react';
import { Helmet } from 'react-helmet-async';
import { useTranslation } from 'react-i18next';
import { BrowserRouter, Outlet, useNavigationType } from 'react-router-dom';
import { useTheme } from 'styled-components';

import { DrumMachineProvider } from 'app/services/DrumMachineService/context';
import { useEffects } from 'app/services/EffectsService/useEffects';
import { GuitarInputProvider } from 'app/services/GuitarInputService/context';
import { useMelodiesSlice } from 'app/services/MelodiesService';

import { FeedbackLink } from 'app/components/FeedbackLink';
import { InputDevicesProvider } from 'app/components/InputDevices';
import { MetronomePlacementProvider } from 'app/components/Metronome';
import { PitchBendIndicator } from 'app/components/PitchBendIndicator';

import { GlobalStyle } from 'styles/global-styles';

import { Routing, useKeyboardScope } from './Routing';
import { SideSection } from './SideSection';
import { Loader } from './components/Loader';
import { useCommonSlice } from './services/CommonService';
import { useKeyboard } from './services/KeyboardService';
import { useTimbre } from './services/SynthesizerService/hooks/useTimbre';

const Workspace = () => {
  useCommonSlice();
  const keyboardScope = useKeyboardScope();
  useKeyboard(keyboardScope);
  useTimbre();
  useEffects();
  useMelodiesSlice();
  const entryNavigation = useRef(useNavigationType());
  useEffect(() => {
    if (entryNavigation.current === 'PUSH') window.scrollTo(0, 0);
  }, []);

  return (
    <DrumMachineProvider>
      <GuitarInputProvider>
        <InputDevicesProvider>
          <MetronomePlacementProvider>
            <SideSection />
            <PitchBendIndicator />
            <Loader />
            <Outlet />
            <FeedbackLink />
          </MetronomePlacementProvider>
        </InputDevicesProvider>
      </GuitarInputProvider>
    </DrumMachineProvider>
  );
};

export const App = () => {
  const theme = useTheme();
  useEffect(() => {
    document
      .getElementById('app-theme-color')
      ?.setAttribute('content', theme.background);
    document
      .getElementById('app-favicon')
      ?.setAttribute(
        'href',
        `${process.env.PUBLIC_URL || ''}/brand/logo-${theme.key}-32.webp`,
      );
  }, [theme]);
  const { i18n } = useTranslation();
  return (
    <BrowserRouter>
      <Helmet
        titleTemplate="%s - Melody Generator"
        defaultTitle="Melody Generator"
        htmlAttributes={{ lang: i18n.language }}
      />
      <Routing workspace={<Workspace />} />
      <GlobalStyle />
    </BrowserRouter>
  );
};
