import { useMemo, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useSelector } from 'react-redux';
import { Link, useNavigate, useParams } from 'react-router-dom';
import styled from 'styled-components';

import {
  PITCH_TOLERANCE,
  createVocalLine,
  frequencyPitch,
  pitchName,
  targetPitch,
  vocalTarget,
} from 'app/services/KaraokeService/score';
import { useKaraoke } from 'app/services/KaraokeService/useKaraoke';
import { selectLibraryMelodies } from 'app/services/MelodiesService';
import { Melody } from 'app/services/MelodiesService/types';
import { selectNotes } from 'app/services/NotesService';

import { HeaderIcon } from 'app/components/HeaderIcon';
import { KaraokeRoll } from 'app/components/KaraokeRoll';

export const KaraokePage = () => {
  const { songId } = useParams();
  const library = useSelector(selectLibraryMelodies).filter(
    melody => melody.notes.length,
  );
  const recording = useSelector(selectNotes).melody;
  const melody =
    songId === 'recording'
      ? recording
      : songId
      ? library.find(item => item.title === songId)
      : library.find(
          item => (item.displayTitle ?? item.title) === 'Ode to Joy',
        ) ?? library[0];
  return melody?.notes.length ? (
    <KaraokeSession
      key={songId ?? 'default'}
      melody={melody}
      library={library}
      recording={recording}
      songId={songId}
    />
  ) : (
    <Page aria-label="Karaoke">
      <h1>This melody has no notes yet</h1>
      <p>
        Choose a melody from the library or record your own in Melody Studio.
      </p>
      <Link to="/karaoke">Choose melody</Link>
      {' · '}
      <Link to="/sandbox/staff">Open Melody Studio</Link>
    </Page>
  );
};

const KaraokeSession = ({
  melody,
  library,
  recording,
  songId,
}: {
  melody: Melody;
  library: Melody[];
  recording: Melody;
  songId?: string;
}) => {
  const navigate = useNavigate();
  const [transpose, setTranspose] = useState(0);
  const [singingOctave, setSingingOctave] = useState(0);
  const [speed, setSpeed] = useState(1);
  const [guide, setGuide] = useState(true);
  const line = useMemo(
    () => createVocalLine(melody.notes, transpose),
    [melody.notes, transpose],
  );
  const game = useKaraoke(melody, line, speed, guide, singingOctave);
  const { input } = game;
  const playing = game.status === 'playing';
  const locked = playing || game.status === 'paused' || game.loading;
  const target = vocalTarget(line, game.elapsed);
  const cents =
    target && input.frequency
      ? 100 *
        (frequencyPitch(input.frequency) - targetPitch(target, game.elapsed))
      : null;
  const accurate = cents !== null && Math.abs(cents) <= PITCH_TOLERANCE;
  const accuracy = game.expected
    ? Math.round((100 * game.matched) / game.expected)
    : 0;
  const feedback =
    game.status === 'finished'
      ? 'Melody complete'
      : !playing
      ? game.status === 'paused'
        ? 'Pause'
        : 'Ready to sing?'
      : game.elapsed < 0
      ? `Get ready: ${Math.ceil(-game.elapsed / speed / 1000)}`
      : !target
      ? 'Rest'
      : cents === null
      ? 'Sing the note'
      : accurate
      ? 'On pitch'
      : cents < 0
      ? 'Sing higher'
      : 'Sing lower';
  const outOfRange = line.some(note => {
    const singingPitch = note.pitch + 12 * singingOctave;
    return singingPitch < 33 || singingPitch > 91;
  });
  return (
    <Page aria-label="Karaoke">
      <Helmet>
        <title>Karaoke · Melody Generator</title>
      </Helmet>
      <Heading>
        <HeaderIcon name="karaoke" />
        <span>KARAOKE</span>
      </Heading>
      <h1>Sing in tune</h1>
      <Intro>
        Follow the melody and compare your pitch with the target line.
      </Intro>
      <Panel aria-label="Karaoke settings">
        <Fields>
          <Field>
            Melody
            <select
              value={songId === 'recording' ? 'recording' : melody.title}
              disabled={locked}
              onChange={event =>
                navigate(`/karaoke/${encodeURIComponent(event.target.value)}`)
              }
            >
              {recording.notes.length > 0 && (
                <option value="recording">Current recording</option>
              )}
              {library.map(item => (
                <option key={item.title} value={item.title}>
                  {item.displayTitle || item.title}
                </option>
              ))}
            </select>
          </Field>
          <Field>
            Vocal register
            <select
              value={transpose}
              disabled={locked}
              onChange={event => setTranspose(Number(event.target.value))}
            >
              {[-24, -12, 0, 12, 24].map(value => (
                <option
                  key={value}
                  value={value}
                  disabled={line.some(
                    note =>
                      note.pitch + value - transpose < 12 ||
                      note.pitch + value - transpose > 119,
                  )}
                >
                  {value === 0
                    ? 'Original'
                    : `${value > 0 ? '+' : '−'}${Math.abs(value / 12)} oct.`}
                </option>
              ))}
            </select>
          </Field>
          <Field>
            Rate
            <select
              value={speed}
              disabled={locked}
              onChange={event => setSpeed(Number(event.target.value))}
            >
              {[0.5, 0.75, 1, 1.25].map(value => (
                <option key={value} value={value}>
                  {value * 100}%
                </option>
              ))}
            </select>
          </Field>
        </Fields>
        <Checkbox>
          <input
            type="checkbox"
            checked={guide}
            disabled={locked}
            onChange={event => setGuide(event.target.checked)}
          />
          Play guide notes
        </Checkbox>
        {outOfRange && (
          <Hint>
            Adjust Vocal register or Singing octave to stay within A1–G6.
          </Hint>
        )}
      </Panel>
      <Panel aria-label="Karaoke microphone">
        <Fields>
          <Field>
            Audio input
            <select
              value={input.deviceId}
              disabled={!input.supported || input.status === 'connecting'}
              onChange={event => input.selectDevice(event.target.value)}
            >
              <option value="">Default microphone</option>
              {input.deviceId &&
                !input.devices.some(
                  device => device.deviceId === input.deviceId,
                ) && (
                  <option value={input.deviceId}>Selected audio input</option>
                )}
              {input.devices
                .filter(device => device.deviceId)
                .map((device, index) => (
                  <option key={device.deviceId} value={device.deviceId}>
                    {device.label || `Microphone ${index + 1}`}
                  </option>
                ))}
            </select>
          </Field>
          <Field>
            Singing octave
            <select
              value={singingOctave}
              disabled={locked}
              aria-describedby="karaoke-singing-octave-hint"
              onChange={event => setSingingOctave(Number(event.target.value))}
            >
              <option value={-1}>One octave below the melody</option>
              <option value={0}>Same as the melody</option>
              <option value={1}>One octave above the melody</option>
            </select>
          </Field>
          {input.status === 'listening' && input.channels > 1 && (
            <Field>
              Channel
              <select
                value={input.channel}
                onChange={event => {
                  game.pause();
                  input.selectChannel(Number(event.target.value));
                }}
              >
                {Array.from({ length: input.channels }, (_, index) => (
                  <option key={index} value={index}>
                    Input {index + 1}
                  </option>
                ))}
              </select>
            </Field>
          )}
          <Button
            type="button"
            disabled={!input.supported}
            onClick={() =>
              input.status === 'idle' ? void input.start() : input.stop()
            }
          >
            {input.status === 'connecting'
              ? 'Cancel connection'
              : input.status === 'listening'
              ? 'Turn off microphone'
              : 'Turn on microphone'}
          </Button>
        </Fields>
        <Hint id="karaoke-singing-octave-hint">
          Choose the octave you want to sing in. The guide stays at the melody’s
          pitch, and the app shows and scores your voice in the melody’s octave.
        </Hint>
        <Level>
          <span>
            {input.status === 'listening' ? 'Voice level' : 'Microphone is off'}
          </span>
          <progress aria-label="Voice level" max="1" value={input.level} />
        </Level>
        {input.clipping && (
          <Hint role="status">
            Clipping. Move away from the microphone or reduce gain.
          </Hint>
        )}
        {input.error && <ErrorMessage role="alert">{input.error}</ErrorMessage>}
        {!input.supported && (
          <ErrorMessage role="alert">
            A browser with microphone access and Web Audio is required. Open the
            app over HTTPS or localhost.
          </ErrorMessage>
        )}
        <Hint>
          Pitch analysis runs on your device. The app does not record or upload
          your voice. Wear headphones to keep the guide out of the microphone.
        </Hint>
      </Panel>
      <Panel aria-label="Vocal practice">
        <Readout $accurate={accurate}>
          <div>
            <small>Melody note</small>
            <strong aria-label="Target note">{target?.note ?? '·'}</strong>
          </div>
          <div>
            <small>Your voice</small>
            <strong aria-label="Voice note">
              {input.frequency
                ? pitchName(frequencyPitch(input.frequency))
                : '·'}
            </strong>
          </div>
          <div>
            <small>Time on pitch</small>
            <strong aria-label="Singing accuracy">
              {game.expected ? `${accuracy}%` : '·'}
            </strong>
          </div>
        </Readout>
        <Feedback role="status" $accurate={accurate}>
          {feedback}
        </Feedback>
        <Hint $center>
          {cents === null
            ? `Pitch tolerance: ±${PITCH_TOLERANCE} cents (half a semitone)`
            : `${cents > 0 ? '+' : '−'}${Math.abs(
                Math.round(cents),
              )} cents from target`}
        </Hint>
        <KaraokeRoll
          line={line}
          elapsed={game.elapsed}
          frequency={input.frequency}
          playing={playing}
          speed={speed}
        />
        <progress
          aria-label="Karaoke progress"
          max={game.duration || 1}
          value={Math.max(0, game.elapsed)}
        />
        <Controls>
          <Button
            type="button"
            disabled={input.status !== 'listening' || game.loading}
            onClick={() => (playing ? game.pause() : void game.start())}
          >
            {game.loading
              ? 'Loading sound…'
              : playing
              ? 'Pause'
              : game.status === 'paused'
              ? 'Resume singing'
              : game.status === 'finished'
              ? 'Sing again'
              : 'Start singing'}
          </Button>
          <Secondary type="button" onClick={game.reset}>
            Restart
          </Secondary>
          {game.status === 'finished' && (
            <Result>
              On pitch: {(game.matched / 1000 / speed).toFixed(1)} of{' '}
              {(game.expected / 1000 / speed).toFixed(1)} sec.
            </Result>
          )}
        </Controls>
        {game.error && <ErrorMessage role="alert">{game.error}</ErrorMessage>}
      </Panel>
      <Help>
        <h2>How to sing</h2>
        <p>
          Turn on your microphone, choose a comfortable register and click Start
          singing. After the countdown, sing the note crossing the vertical
          line. You can sing a vowel or hum.
        </p>
        <p>
          Accuracy is the share of each note’s time you sing within ±50 cents of
          the target, in the right octave. Silence during a note lowers the
          score. Rests do not count. The session pauses if you hide the window
          or disconnect the mic.
        </p>
        <p>
          Karaoke shows notes and uses the highest note in each chord. For an
          imported song, open Details in Melody Studio and select the vocal
          track. Sing in a quiet room so the app can follow one voice. The pitch
          line appears with a short delay.
        </p>
      </Help>
    </Page>
  );
};

