import { useRef, useState } from 'react';
import styled from 'styled-components';

import {
  formatGuitarNote,
  guitarFrets,
  guitarStrings,
  maxBendCents,
  noteAtFret,
} from 'app/services/VirtualGuitarService/fretboard';
import { useVirtualGuitar } from 'app/services/VirtualGuitarService/useVirtualGuitar';

import { FretInlays, FretMarkerStyle } from './FretMarkers';
import { GuitarTab } from './GuitarTab';
import {
  Board,
  BoardLabels,
  BoardPanel,
  Cell,
  Feedback,
  Neck,
  NeckScroll,
  StringLines,
} from './styles';

const columns = guitarFrets.length;
const stringCount = guitarStrings.length;

export const Fretboard = ({
  className,
  enabled = true,
  markers = 'dots',
}: {
  className?: string;
  enabled?: boolean;
  markers?: FretMarkerStyle;
}) => {
  const [focused, setFocused] = useState(0);
  const cells = useRef<(HTMLButtonElement | null)[]>([]);
  const guitar = useVirtualGuitar(enabled);

  return (
    <GuitarPanel className={className}>
      <GuitarTab notes={guitar.tab} />
      <BoardPanel aria-label="Guitar fretboard">
        <NeckScroll>
          <Neck>
            <BoardLabels aria-hidden="true">
              {guitarFrets.map(fret => (
                <span key={fret}>{fret || 'Open'}</span>
              ))}
            </BoardLabels>
            <Board>
              <FretInlays markers={markers} />
              <StringLines
                aria-hidden="true"
                viewBox={`0 0 ${columns} ${stringCount}`}
                preserveAspectRatio="none"
              >
                {guitarStrings.map((open, row) => {
                  const note = guitar.active.find(
                    active => active.string === row,
                  );
                  const gesture = note?.gesture;
                  const x = (gesture?.fret ?? note?.fret ?? 0) + 0.5;
                  const y = row + 0.5;
                  const offset = gesture
                    ? (gesture.bendCents / maxBendCents) *
                      gesture.bendDirection *
                      0.4
                    : 0;
                  const path = `M0 ${y} Q${x / 2} ${y} ${x} ${y + offset} Q${
                    (x + columns) / 2
                  } ${y} ${columns} ${y}`;
                  const wound = row >= 3;
                  const thickness = wound
                    ? 2.6 + (row - 3) * 0.45
                    : 1 + row * 0.22;
                  return (
                    <g key={open}>
                      <path
                        d={path}
                        strokeWidth={thickness}
                        vectorEffect="non-scaling-stroke"
                        data-active={note ? true : undefined}
                        data-wound={wound || undefined}
                      />
                      {wound && (
                        <path
                          d={path}
                          strokeWidth={thickness - 0.35}
                          vectorEffect="non-scaling-stroke"
                          data-winding
                        />
                      )}
                    </g>
                  );
                })}
              </StringLines>
              {guitarStrings.flatMap((open, row) =>
                guitarFrets.map((fret, col) => {
                  const index = row * columns + col;
                  const note = formatGuitarNote(noteAtFret(row, fret));
                  const playing = guitar.active.some(
                    active =>
                      active.string === row &&
                      (active.gesture?.fret ?? active.fret) === fret,
                  );
                  return (
                    <Cell
                      key={`${open}:${col}`}
                      ref={element => {
                        cells.current[index] = element;
                      }}
                      type="button"
                      aria-label={`String ${row + 1}, ${
                        fret ? `fret ${fret}` : 'open'
                      }, ${note}`}
                      data-open={fret === 0 ? true : undefined}
                      data-playing={playing ? true : undefined}
                      tabIndex={index === focused ? 0 : -1}
                      onFocus={() => setFocused(index)}
                      onKeyDown={event => {
                        let nextRow = row;
                        let nextCol = col;
                        switch (event.key) {
                          case 'ArrowUp':
                            nextRow--;
                            break;
                          case 'ArrowDown':
                            nextRow++;
                            break;
                          case 'ArrowLeft':
                            nextCol--;
                            break;
                          case 'ArrowRight':
                            nextCol++;
                            break;
                          default:
                            return;
                        }
                        event.preventDefault();
                        if (
                          nextRow >= 0 &&
                          nextRow < stringCount &&
                          nextCol >= 0 &&
                          nextCol < columns
                        )
                          cells.current[nextRow * columns + nextCol]?.focus();
                      }}
                      onClick={event => {
                        if (event.detail === 0)
                          guitar.play(-1 - row, row, fret);
                      }}
                      onPointerDown={event => {
                        if (event.button !== 0) return;
                        event.preventDefault();
                        const cell = event.currentTarget;
                        cell.setPointerCapture(event.pointerId);
                        guitar.play(event.pointerId, row, fret, {
                          y: event.clientY,
                          type: event.pointerType,
                        });
                      }}
                      onPointerMove={event => {
                        const { left, width } =
                          event.currentTarget.getBoundingClientRect();
                        if (!width) return;
                        guitar.move(
                          event.pointerId,
                          event.clientY,
                          (event.clientX - left) / width,
                        );
                      }}
                      onPointerUp={event => guitar.release(event.pointerId)}
                      onPointerCancel={event => guitar.cancel(event.pointerId)}
                      onLostPointerCapture={event =>
                        guitar.loseCapture(event.pointerId)
                      }
                      onContextMenu={event => event.preventDefault()}
                    >
                      <span aria-hidden="true">{note}</span>
                    </Cell>
                  );
                }),
              )}
            </Board>
          </Neck>
        </NeckScroll>
        <Feedback>
          {guitar.status === 'loading' && (
            <span role="status">Loading guitar sound…</span>
          )}
          {guitar.status === 'error' && (
            <>
              <ErrorText role="alert">Could not start guitar audio.</ErrorText>
              <button type="button" onClick={guitar.retry}>
                Retry
              </button>
            </>
          )}
        </Feedback>
      </BoardPanel>
    </GuitarPanel>
  );
};

const ErrorText = styled.span`
  color: ${p => p.theme.danger};
`;

const GuitarPanel = styled.div`
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  gap: 6px;
`;
