import {
  cropExpression,
  pitchAt,
} from 'app/services/MelodiesService/expression';
import { getNoteDuration } from 'app/services/MelodiesService/timing';
import { Melody, NoteInMelody } from 'app/services/MelodiesService/types';
import { Note } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';

export type VocalNote = NoteInMelody & { duration: number; pitch: number };
export const PITCH_TOLERANCE = 50;
export const VOCAL_MAX_FREQUENCY = 1600;
export const frequencyPitch = (frequency: number) =>
  69 + 12 * Math.log2(frequency / 440);
export const pitchName = (pitch: number): Note =>
  `${chromaticNotes[((Math.round(pitch) % 12) + 12) % 12]}${
    Math.floor(Math.round(pitch) / 12) - 1
  }` as Note;
const notePitch = (note: Note) =>
  (Number(note.slice(-1)) + 1) * 12 +
  chromaticNotes.findIndex(name => name === note.slice(0, -1));

// A voice follows one line. For overlapping parts, take the highest written
// pitch at each boundary; resume the lower voice when the upper one ends.
export const createVocalLine = (notes: Melody['notes'], transpose = 0) => {
  const events = notes.flatMap((note, index) => [
    { time: note.start, index, on: true },
    { time: note.start + getNoteDuration(note), index, on: false },
  ]);
  events.sort((a, b) => a.time - b.time || Number(a.on) - Number(b.on));
  const active = new Set<number>();
  const pitches = notes.map(note => notePitch(note.note) + transpose);
  const segments: { index: number; start: number; end: number }[] = [];
  for (let i = 0; i < events.length; ) {
    const start = events[i].time;
    while (i < events.length && events[i].time === start) {
      const event = events[i++];
      if (event.on) active.add(event.index);
      else active.delete(event.index);
    }
    const end = events[i]?.time;
    if (end === undefined || end <= start || !active.size) continue;
    let index = -1;
    active.forEach(candidate => {
      if (index < 0 || pitches[candidate] > pitches[index]) index = candidate;
    });
    const previous = segments[segments.length - 1];
    if (previous?.index === index && previous.end === start) previous.end = end;
    else segments.push({ index, start, end });
  }
  return segments.map(({ index, start, end }): VocalNote => {
    const source = notes[index];
    const duration = getNoteDuration(source);
    return {
      note: pitchName(pitches[index]),
      pitch: pitches[index],
      start,
      duration: end - start,
      expression: cropExpression(
        source.expression,
        (start - source.start) / duration,
        (end - source.start) / duration,
      ),
    };
  });
};

export const vocalTarget = (line: VocalNote[], time: number) =>
  line.find(note => note.start <= time && time < note.start + note.duration);

export const targetPitch = (note: VocalNote, time: number) =>
  note.pitch +
  (note.expression
    ? pitchAt(note.expression.points, (time - note.start) / note.duration) / 100
    : 0);

// Song time is in milliseconds. A note owns [start, end), rests own no score.
// Only the recently observed part of a delayed frame can earn credit.
export const scoreVocalInterval = (
  line: VocalNote[],
  from: number,
  to: number,
  frequency: number | null,
  creditFrom = from,
) => {
  let expected = 0;
  let matched = 0;
  line.forEach(note => {
    const start = Math.max(from, note.start);
    const end = Math.min(to, note.start + note.duration);
    if (end <= start) return;
    expected += end - start;
    const audibleStart = Math.max(start, creditFrom);
    if (audibleStart >= end || !frequency || !Number.isFinite(frequency))
      return;
    const cents =
      100 *
      (frequencyPitch(frequency) - targetPitch(note, (audibleStart + end) / 2));
    if (Math.abs(cents) <= PITCH_TOLERANCE + 1e-7)
      matched += end - audibleStart;
  });
  return { expected, matched };
};
