import { useEffect, useState } from 'react';
import { useSelector, useStore } from 'react-redux';

import type { Melody } from 'app/services/MelodiesService/types';
import { useCurrentMelody } from 'app/services/MelodiesService/useCurrentMelody';
import {
  initialState,
  selectCompletedRecording,
  selectNotes,
} from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';
import type { RootState } from 'app/services/types';

const LIVE_SCORE_NOTE_LIMIT = 64;
const LIVE_SCORE_REFRESH_MS = 50;
export const liveScoreHint =
  'Showing recent notes. The full recording is available after Stop.';

export const useRecordingScore = (trackHeldNotes = false) => {
  const store = useStore<RootState>();
  const isRecording = useSelector(state => selectSettings(state).isRecording);
  const version = useSelector(state => selectNotes(state).recordingVersion);
  const completed = useSelector(selectCompletedRecording);
  const [frame, setFrame] = useState<{
    version: number;
    melody: Melody;
    skipped: number;
    now: number;
  }>();

  useEffect(() => {
    if (!isRecording) return;
    // Sample only the display. Capture still writes to the store immediately,
    // even when the browser throttles this timer.
    let previous: Melody | undefined;
    let tail = initialState.melody;
    let skipped = 0;
    let hasHeldNotes = false;
    const refresh = () => {
      const { melody } = selectNotes(store.getState());
      const changed = previous !== melody;
      if (changed) {
        previous = melody;
        skipped = Math.max(0, melody.notes.length - LIVE_SCORE_NOTE_LIMIT);
        tail = skipped
          ? { ...melody, notes: melody.notes.slice(skipped) }
          : melody;
        hasHeldNotes =
          trackHeldNotes &&
          tail.notes.some(note => note.duration === undefined);
      }
      if (changed || hasHeldNotes)
        setFrame({ version, melody: tail, skipped, now: Date.now() });
    };
    refresh();
    const timer = window.setInterval(refresh, LIVE_SCORE_REFRESH_MS);
    return () => window.clearInterval(timer);
  }, [isRecording, store, trackHeldNotes, version]);

  const live = isRecording && frame?.version === version ? frame : undefined;
  const melody = useCurrentMelody(
    live?.melody ?? completed ?? initialState.melody,
  )!;
  return {
    melody,
    isRecording,
    skipped: live?.skipped ?? 0,
    now: live?.now ?? 0,
  };
};
