import { fitToBar, phraseArrangement } from './arrangement';
import { phraseHarmony } from './harmony';
import { GenerationSettings, moods, rhythms } from './options';

export interface PhraseNote {
  midi: number;
  start: number;
  length: number;
}

export const composePhrase = (
  settings: GenerationSettings,
  random = Math.random,
) => {
  const { bars } = settings;
  const { progressions, motif } = moods[settings.mood];
  const rhythm = rhythms[settings.rhythm];
  const { barSteps, beatSteps, groove, chordNotes } =
    phraseArrangement(settings);
  const melodyOnsets = rhythm.melody.map(onsets => fitToBar(onsets, barSteps));
  const { pitch, size, flavor, midiFor, degreeFor, chordAt } =
    phraseHarmony(settings);
  const leadSteps = Math.ceil(size * 1.4);
  const patterns = progressions[flavor];
  const degrees = Array.from(
    { length: Math.ceil(bars / 4) },
    () => patterns[Math.floor(random() * patterns.length)],
  )
    .flat()
    .slice(0, bars);
  const motifOffset = Math.floor(random() * 3);
  degrees[bars - 2] = degrees[bars - 3] === 4 ? 3 : 4;
  degrees[bars - 1] = 0;

  const melody: PhraseNote[] = [];
  const accompaniment: PhraseNote[] = [];
  const bassNotes: PhraseNote[] = [];
  const drumNotes: PhraseNote[] = [];
  const chords = degrees.map(degree => chordAt(degreeFor(degree)));
  const motifStep = (value: number) =>
    Math.round((value * (leadSteps - 1)) / 9);
  let previous = motifStep(motif[motifOffset]);
  chords.forEach(({ steps: chordDegrees }, bar) => {
    const offset = bar * barSteps;
    const final = bar === bars - 1;
    const onsets = melodyOnsets[bar % 2];
    const chordSteps = Array.from(
      { length: leadSteps },
      (_, step) => step,
    ).filter(step =>
      chordDegrees.some(degree => degree % size === step % size),
    );
    const steps = onsets.map((_, i) => {
      if (final && i === onsets.length - 1)
        return previous < size / 2 ? 0 : size;
      const target = motifStep(
        motif[(i + motifOffset) % motif.length] + (bar % 4 === 2 ? 1 : 0),
      );
      const cost = (step: number) =>
        2 * Math.abs(step - target) + Math.abs(step - previous);
      previous = chordSteps.reduce((best, step) =>
        cost(step) < cost(best) ? step : best,
      );
      return previous;
    });

    onsets.forEach((onset, i) => {
      let step = steps[i];
      // Fill an offbeat only when it sits between consecutive beat attacks.
      const left = onsets[i - 1];
      const right = onsets[i + 1];
      if (left % beatSteps === 0 && right - left === beatSteps) {
        const before = steps[i - 1];
        const after = steps[i + 1];
        const neighbor = before === 0 ? 1 : before - 1;
        if (Math.abs(before - after) === 2) {
          const passing = (before + after) / 2;
          if (
            Math.abs(midiFor(passing) - midiFor(before)) <= 2 &&
            Math.abs(midiFor(passing) - midiFor(after)) <= 2
          )
            step = passing;
        } else if (
          before === after &&
          Math.abs(midiFor(neighbor) - midiFor(before)) <= 2
        )
          step = neighbor;
      }
      melody.push({
        midi: midiFor(step),
        start: offset + onset,
        length: (right ?? barSteps) - onset,
      });
    });

    const chord = chordDegrees.map(step => 48 + (midiFor(step) % 12));
    accompaniment.push(...chordNotes(chord, offset, final));
    if (settings.bass)
      bassNotes.push({ midi: chord[0] - 12, start: offset, length: barSteps });
    drumNotes.push(
      ...groove.map(note => ({ ...note, start: offset + note.start })),
    );
  });

  return {
    ...settings,
    pitch,
    chords: chords.map(chord => chord.label),
    melody,
    accompaniment,
    bassNotes,
    drumNotes,
  };
};

export type Phrase = ReturnType<typeof composePhrase>;
