import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import {
  FretMarkerPreview,
  FretMarkerStyle,
  fretMarkerOptions,
} from 'app/components/VirtualGuitar/FretMarkers';
import { Fretboard } from 'app/components/VirtualGuitar/Fretboard';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

import { readPreferences, writePreferences } from 'utils/preferences';

const preferencesKey = 'qwertophone.virtual-guitar.v1';

export const VirtualGuitarPage = () => {
  const [markers, setMarkers] = useState<FretMarkerStyle>(() => {
    const saved = readPreferences(preferencesKey).markers;
    return (
      fretMarkerOptions.find(option => option.value === saved)?.value ?? 'dots'
    );
  });

  return (
    <Page aria-labelledby="virtual-guitar-title" data-local-space-key>
      <Helmet>
        <title>Virtual Guitar</title>
      </Helmet>
      <Heading id="virtual-guitar-title">Virtual Guitar</Heading>
      <Fretboard markers={markers} />
      <MarkerOptions role="group" aria-label="Fret markers">
        {fretMarkerOptions.map(({ value, label }) => (
          <MarkerButton
            key={value}
            type="button"
            aria-label={label}
            aria-pressed={markers === value}
            onClick={() => {
              setMarkers(value);
              writePreferences(preferencesKey, { markers: value });
            }}
          >
            <FretMarkerPreview markers={value} />
          </MarkerButton>
        ))}
      </MarkerOptions>
    </Page>
  );
};

const Page = styled(PageWrapper)`
  max-width: none;

  @media (max-width: 520px) {
    padding-top: 12px;
  }
`;

const Heading = styled.h1`
  margin: 8px 0 24px;
  text-align: center;
  font: inherit;
  font-size: clamp(32px, 5vw, 52px);
  font-weight: 700;
  letter-spacing: -0.045em;
  line-height: 1.12;

  @media (max-width: 520px) {
    margin: 0 0 12px;
    font-size: 28px;
  }
`;

const MarkerOptions = styled.div`
  display: grid;
  grid-template-columns: repeat(${fretMarkerOptions.length}, minmax(0, 60px));
  justify-content: center;
  gap: 6px;
  margin-top: 10px;
`;

const MarkerButton = styled.button`
  display: grid;
  place-items: center;
  min-height: 44px;
  min-width: 0;
  padding: 3px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 7px;
  background: ${p => p.theme.surface};
  cursor: pointer;

  &[aria-pressed='true'] {
    border-color: ${p => p.theme.primary};
    box-shadow: inset 0 0 0 1px ${p => p.theme.primary};
  }

  &:hover {
    background: ${p => p.theme.borderLight};
  }

  &:focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: 1px;
  }

  > svg {
    display: block;
    width: 100%;
  }
`;
