export const getTimbrePresentation = (timbre: Timbre): Presentation =>
  presentations[timbre] ?? {
    label: timbre,
    family: 'keys',
    artwork: 'synth',
  };

export const instrumentImage = (artwork: string) =>
  `${process.env.PUBLIC_URL || ''}/images/instruments/${artwork}.webp`;

// Put one of each instrument first so the initial view shows the range of sounds.
