export const timbreOptions = timbresLinks
  .map(({ title }) => ({ id: title, ...getTimbrePresentation(title) }))
  .sort((a, b) => {
    const rank = (id: Timbre) => {
      const index = featured.indexOf(id);
      return index === -1 ? featured.length : index;
    };
    return rank(a.id) - rank(b.id) || a.label.localeCompare(b.label, 'en');
  });
