import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNote, splitNote } from 'app/services/NotesService/noteUtils';
import { Note, Octave } from 'app/services/NotesService/types';
import { tunings } from 'app/services/TunerService/pitch';

export const guitarStrings = [...tunings.standard.notes].reverse();
export const guitarFrets = Array.from({ length: 25 }, (_, fret) => fret);
export const maxBendCents = 200;
const bendDeadZone = 4;

export const noteAtFret = (string: number, fret: number): Note => {
  const [pitch, octave] = splitNote(guitarStrings[string]);
  const index = chromaticNotes.indexOf(pitch) + fret;
  return getNote(
    chromaticNotes[index % 12],
    (octave + Math.floor(index / 12)) as Octave,
  );
};

export const bendAtDistance = (deltaY: number) =>
  Math.min(1, Math.max(0, (Math.abs(deltaY) - bendDeadZone) / 56)) *
  maxBendCents;

export const slideFret = (startFret: number, cellOffset: number) =>
  Math.max(
    0,
    Math.min(guitarFrets.length - 1, startFret + Math.floor(cellOffset)),
  );

export const formatGuitarNote = (note: Note) => note.replace('#', '♯');
