import { readPreferences, writePreferences } from 'utils/preferences';

export const CONNECTIONS_KEY = 'qwertophone.connections.v1';

export interface ConnectionPreferences {
  tab: 'midi' | 'audio';
  midiEnabled: boolean;
  midiInputId: string;
}

export const loadConnections = (): ConnectionPreferences => {
  const saved = readPreferences(CONNECTIONS_KEY);
  return {
    tab: saved.tab === 'audio' ? 'audio' : 'midi',
    midiEnabled: saved.midiEnabled === true,
    midiInputId: typeof saved.midiInputId === 'string' ? saved.midiInputId : '',
  };
};

export const saveConnections = (changes: Partial<ConnectionPreferences>) =>
  writePreferences(CONNECTIONS_KEY, { ...loadConnections(), ...changes });
